import csv

DATA = "/app/dataset"


def _num(s: str) -> float:
    return float(s.replace(",", "."))


def answer() -> int:
    # Catalog: unit_price uses decimal commas for some rows; dispatches may
    # reference a product by EAN code instead of product_id.
    prices, ean_to_pid = {}, {}
    with open(f"{DATA}/product_catalog.csv", newline="") as f:
        for r in csv.DictReader(f):
            prices[r["product_id"]] = _num(r["unit_price"])
            ean_to_pid[r["ean_code"]] = r["product_id"]

    # Spoilage disposal: the 2023-07-18 03:17:00 bulk dispatch of only Meat and
    # Frozen goods, at 3 AM, during the overnight Meat/Frozen temperature breach.
    disposal_ts = "2023-07-18 03:17:00"

    seen, total = set(), 0.0
    with open(f"{DATA}/warehouse_dispatches.csv", newline="") as f:
        for r in csv.DictReader(f):
            pid = ean_to_pid.get(r["product_id"], r["product_id"])
            key = (r["timestamp"], pid, r["quantity"], r["total_weight_kg"])
            if key in seen:  # duplicate log rows (2023-07-10..14)
                continue
            seen.add(key)
            if r["timestamp"] == disposal_ts:
                continue
            total += int(r["quantity"]) * prices[pid]
    return int(round(total))


if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

